				else if (!isLocalLaunch && connectedToDebugServer && firstLaunch &&
					Settings::Instance()->Get<bool>("debugger.confirmFirstLaunch"))
				{
					auto remoteHost = QString::fromStdString(controller->GetRemoteHost());
